38	func (l *replicateInputLog) UnmarshalJSON(data []byte) error {
39		return unmarshalLastWinsArray(data, (*[]mevwatch.LogEntry)(l))
40	}
41	
42	// replicateInputRequest 是读取阶段的复制请求：它以库类型
43	// mevwatch.AppendRequest 为底层类型另行定义，底层布局逐字段一致，请求字段
44	// 只在 mevwatch 包定义一次，CLI 不再平行维护整套同名字段。单独留这一层类型
45	// 只为挂载输入特有的解码规则——entries 在同一请求对象里重复出现时必须整体
46	// 替换（见 UnmarshalJSON）。读完后整个值可直接转换回 mevwatch.AppendRequest，
47	// 无须逐字段搬运。
48	type replicateInputRequest mevwatch.AppendRequest
49	
50	// requestUnmarshalShape 是单个请求对象的解码形状：内嵌的
51	// mevwatch.AppendRequest 提供全部请求字段（term、prevLogIndex、prevLogTerm、
52	// leaderCommit），外层同名字段 entries 按 encoding/json 的字段遮蔽规则压过内嵌
53	// 的 Entries，于是 entries 只解进带整体替换规则的 replicateInputEntries，其余
54	// 字段仍直接落在库类型上。它只是 UnmarshalJSON 内的一个局部解码形状，不构成
55	// 第二套请求字段，也不会出现在任何错误信息里（见 normalizeRequestJSONError）。
56	type requestUnmarshalShape struct {
57		mevwatch.AppendRequest
58		Entries replicateInputEntries `json:"entries"`
59	}
60	
61	// UnmarshalJSON 按整体替换规则解码一个请求：entries 的每一次出现都解进全新
62	// 切片并整体替换，其余请求字段与库共用同一套定义。解完把整体替换后的 entries
63	// 放回内嵌的库请求，再把整个值转换成本类型，全程没有逐字段重新组装。内嵌解码
64	// 产出的 JSON 类型错误经 normalizeRequestJSONError 改写成整理前的稳定文本。
65	func (r *replicateInputRequest) UnmarshalJSON(data []byte) error {
66		var shape requestUnmarshalShape
67		if err := json.Unmarshal(data, &shape); err != nil {
68			return normalizeRequestJSONError(err)
69		}
70		shape.AppendRequest.Entries = []mevwatch.LogEntry(shape.Entries)
71		*r = replicateInputRequest(shape.AppendRequest)
72		return nil
73	}
74	
75	// replicateInputRequests 是根对象的 requests 字段：重复出现时最后一份数组
76	// 整体替换，而不是把后一份请求按下标并进前一份。它的底层类型直接就是
77	// []mevwatch.AppendRequest：每一份数组整体解进全新的 []replicateInputRequest
78	// （元素与库类型布局一致、仅差一层不带方法的定义类型），转换后即可整份交给
79	// 复制处理，既没有平行请求字段，也不需要逐请求、逐字段重新组装。
80	type replicateInputRequests []mevwatch.AppendRequest
81	
82	func (r *replicateInputRequests) UnmarshalJSON(data []byte) error {
83		// 仍须先解进局部切片再整体替换：与 unmarshalLastWinsArray 同理，直接解到
84		// r 会让重复出现的 requests 只按下标覆盖，短数组尾部与省略字段都残留上一
85		// 份请求的内容。元素经整体值转换直接成为库类型（两边底层布局逐字段一致），
86		// 转换不出现任何请求字段名：请求含义只在 mevwatch.AppendRequest 一处定义。
87		var next []replicateInputRequest
88		if err := json.Unmarshal(data, &next); err != nil {
89			return err
90		}
91		requests := make([]mevwatch.AppendRequest, len(next))
92		for i := range next {
93			requests[i] = mevwatch.AppendRequest(next[i])
94		}
95		*r = requests
96		return nil
97	}
98	
99	// replicateInputEntries 是单个请求内的 entries 字段：同一请求对象里重复
100	// 出现时，最后一份条目数组整体替换。
101	type replicateInputEntries []mevwatch.LogEntry
102	
103	func (e *replicateInputEntries) UnmarshalJSON(data []byte) error {
104		return unmarshalLastWinsArray(data, (*[]mevwatch.LogEntry)(e))
105	}
106	
107	// normalizeRequestJSONError 把请求对象内嵌解码产出的 JSON 类型错误改写成整理
108	// 前的稳定文本。requestUnmarshalShape 为遮蔽内嵌 Entries 而内嵌了
109	// AppendRequest：encoding/json 会 (1) 在内嵌字段的字段路径里插入中间匿名段
110	// "AppendRequest"，(2) 在整个请求值类型错误（如数组元素不是对象）时把匿名
111	// shape 结构体写进类型名。这些都是实现细节，整理前的文本分别使用请求字段的
112	// 直接路径（requests.term）与类型名 replicateInputRequest，这里统一改回。
113	// 非类型错误（语法错误等）原样返回。
114	func normalizeRequestJSONError(err error) error {
115		var te *json.UnmarshalTypeError
116		if !errors.As(err, &te) {
117			return err
118		}
119		fixed := *te
120		fixed.Field = strings.TrimPrefix(fixed.Field, "AppendRequest.")
121		if fixed.Type == reflect.TypeOf(requestUnmarshalShape{}) {
122			fixed.Type = reflect.TypeOf(replicateInputRequest{})
123		}
124		return &fixed
125	}
126	
127	// unmarshalLastWinsArray 把一次数组字段出现解进一份全新的切片，并用它整体
128	// 替换 dst。它必须先解进局部切片而不能直接解到 dst：encoding/json 对“非 nil
129	// 现有切片 + 重复数组键”只做下标覆盖，短数组的尾部与元素内省略的字段都会
130	// 残留上一次出现的内容。null 与既有行为一致，把目标置为空切片（nil）。
131	func unmarshalLastWinsArray[T any](data []byte, dst *[]T) error {
132		var next []T
133		if err := json.Unmarshal(data, &next); err != nil {
134			return err
135		}
136		*dst = next
137		return nil
138	}
139	
140	// runReplicate 从标准输入读取一份 JSON（初始状态 + 顺序到达的复制请求），
141	// 把逐次接收结果与最终日志作为一份 JSON 写到标准输出。
142	// 初始状态非法或 JSON 无法解析时，以非零退出码和明确错误结束。
143	func runReplicate() int {
144		return runReplicateIO(os.Stdin, os.Stdout, os.Stderr)
145	}
146	
147	func runReplicateIO(stdin io.Reader, stdout, stderr io.Writer) int {
148		data, err := io.ReadAll(stdin)
149		if err != nil {
150			fmt.Fprintf(stderr, "replicate: read stdin: %v\n", err)
151			return 1
152		}
153		// 语法检查用 UseNumber 流式解码而不是解进 interface{}：后者把每个数字
154		// 都转成 float64，未知字段里 1e400 这类超出浮点范围但完全合法的 JSON
155		// 数字会让整份输入在解析阶段被误判为输入错误。未知字段不参与跟随者
156		// 状态计算，其数值大小不应决定输入能否解析；UseNumber 把数字保留为
157		// 原始字面量，只校验语法不做范围转换。已识别数值字段上的同类大数仍由
158		// 随后的类型化解码按既有整数范围限制拒绝。
159		syntaxDec := json.NewDecoder(bytes.NewReader(data))
160		syntaxDec.UseNumber()
161		var syntaxCheck interface{}
162		if err := syntaxDec.Decode(&syntaxCheck); err != nil {
163			fmt.Fprintf(stderr, "replicate: parse input JSON: %v\n", err)
164			return 1
165		}
166		// 与 json.Unmarshal 一致：一份完整文档之后不允许再跟另一份 JSON 或
167		// 其他内容。
168		if syntaxDec.More() {
169			fmt.Fprintf(stderr, "replicate: parse input JSON: unexpected data after top-level JSON value\n")
170			return 1
171		}
172		// 已识别的数值字段被显式写成 null 时，类型化解码会静默当成零值继续
173		// 处理（例如 committedIndex 为 null 被当成“尚未提交”），必须在读取
174		// 输入阶段把整份输入作为字段类型错误拒绝。检查直接扫描 JSON token
175		// 而不是先解进 map：map 解码对重复键只保留最后一次出现，既会漏掉
176		// 写在数字前面的 null，也会让后出现的 log/requests/entries 数组盖掉
177		// 前一份数组，因此重复键的每一次出现都必须单独检查。
178		if path := nullNumericFieldPath(data); path != "" {
179			fmt.Fprintf(stderr, "replicate: invalid field type: %s must be a number, got null\n", path)
180			return 1
181		}
182		var input replicateInput
183		if err := json.Unmarshal(data, &input); err != nil {
184			fmt.Fprintf(stderr, "replicate: parse input JSON: %v\n", err)
185			return 1
186		}
187		// 三个数组经整体替换解码后直接就是库类型，不再逐请求、逐字段重新组装：
188		// log 与 requests 各做一次整切片拷贝（log 顺带从命名类型转换），转换只按
189		// 最后一份数组的实际内容进行，不携带任何同名前序数组的条目字段。requests
190		// 的底层类型即为 []mevwatch.AppendRequest，拷贝后整份交给复制处理。
191		initialLog := append([]mevwatch.LogEntry(nil), input.Log...)
192		requests := append([]mevwatch.AppendRequest(nil), input.Requests...)
193		output, err := mevwatch.ReplicateWithOptions(mevwatch.InitialState{
194			CurrentTerm:    input.CurrentTerm,
195			CommittedIndex: input.CommittedIndex,
196			Log:            initialLog,
197		}, requests, mevwatch.ReplicateOptions{ApplyKV: input.ApplyKV})
198		if err != nil {
199			fmt.Fprintf(stderr, "replicate: %v\n", err)
200			return 1
201		}
202		encoded, err := json.MarshalIndent(output, "", "  ")
203		if err != nil {
204			fmt.Fprintf(stderr, "replicate: encode output JSON: %v\n", err)
205			return 1
206		}
207		fmt.Fprintln(stdout, string(encoded))
208		return 0
209	}
210	
211	// objectSchema 描述某一层次对象里已识别的字段：numerics 是显式写成 null 时
212	// 必须拒绝整份输入的数值字段（标准拼写），arrays 是元素为对象的数组字段及其
213	// 元素层次。字段名识别与 encoding/json 一致，只改变字母大小写的写法同样命中；
214	// 错误位置始终使用这里的标准拼写而不是输入里的大小写变体。根状态、复制请求
215	// 与日志条目共用同一套扫描逻辑，区别只在下面三份 schema。
216	type objectSchema struct {
217		numerics []string
218		arrays   []arrayField
219	}
220	
221	// arrayField 是一个已识别的对象数组字段：name 为标准字段名，elem 为数组元素
222	// 所在层次的 schema。
223	type arrayField struct {
224		name string
225		elem *objectSchema
226	}
227	
228	var (
229		// 日志条目层次：log[i] 与 requests[r].entries[i] 是同一种对象。
230		entryObjectSchema = &objectSchema{numerics: []string{"index", "term"}}
231		// 复制请求层次：数值字段外还嵌套 entries 条目数组。
232		requestObjectSchema = &objectSchema{
233			numerics: []string{"term", "prevLogIndex", "prevLogTerm", "leaderCommit"},
234			arrays:   []arrayField{{name: "entries", elem: entryObjectSchema}},
235		}
236		// 根输入层次：初始状态的数值字段外还嵌套 log 与 requests 两个数组。
237		rootObjectSchema = &objectSchema{
238			numerics: []string{"currentTerm", "committedIndex"},
239			arrays: []arrayField{
240				{name: "log", elem: entryObjectSchema},
241				{name: "requests", elem: requestObjectSchema},
242			},
243		}
244	)
245	
246	// numericName 在 key 命中本层次某个已识别数值字段时返回它的标准拼写。
247	func (s *objectSchema) numericName(key string) (string, bool) {
248		for _, name := range s.numerics {
249			if strings.EqualFold(key, name) {
250				return name, true
251			}
252		}
253		return "", false
254	}
255	
256	// arrayField 在 key 命中本层次某个已识别数组字段时返回它的定义（含标准拼写）。
257	func (s *objectSchema) arrayField(key string) (arrayField, bool) {
258		for _, field := range s.arrays {
259			if strings.EqualFold(key, field.name) {
260				return field, true
261			}
262		}
263		return arrayField{}, false
264	}
265	
266	// nullNumericFieldPath 扫描整份输入 JSON 的 token 流，查找第一个被显式写成
267	// null 的已识别数值字段，返回它的完整位置；没有时返回空串。检查范围是初始
268	// 状态（currentTerm、committedIndex、log[i].index、log[i].term）与每条复制
269	// 请求（term、prevLogIndex、prevLogTerm、leaderCommit 及 entries[j].index、
270	// entries[j].term）；请求与条目下标从 0 开始，例如第二条请求的提交位置记为
271	// requests[1].leaderCommit。
272	//
273	// 必须扫描 token 而不能先解进 map[string]interface{}：map 解码遇到重复键只
274	// 保留最后一次出现的值。{"currentTerm":null,"currentTerm":1} 里先出现的
275	// null 会因此漏检；log/requests/entries 自身重复出现时，前一份数组里的数值
276	// null 也会被后一份数组盖掉。token 流保留键的每一次出现，重复字段无论 null
277	// 在数字之前还是之后、数组字段重复多少次、拼写是否只改变大小写，都逃不过
278	// 检查。数组字段本身为 null、未知键（含未知对象里的同名键）里的 null 不在
279	// 检查范围内，扫描时只按结构识别已知字段，不进入其他对象与数组。
280	func nullNumericFieldPath(data []byte) string {
281		dec := json.NewDecoder(bytes.NewReader(data))
282		// 数字一律按原始字面量（json.Number）读取：默认的 Token 行为会把数字
283		// 转成 float64，未知字段里 1e400 这类超出浮点范围的合法数字会让扫描
284		// 中途出错返回，从而遮住排在其后的真实数值 null。这里只关心结构，
285		// 不需要任何数值转换。
286		dec.UseNumber()
287	
288		// 取根对象的第一个 token；输入不是对象或 JSON 非法时没有可报告的数值
289		// 字段位置，交由随后的类型化解码产出既有的解析错误。
290		tok, err := dec.Token()
291		if err != nil || tok != json.Delim('{') {
292			return ""
293		}
294		return scanObjectFields(dec, rootObjectSchema, "")
295	}
296	
297	// scanObjectFields 扫描一个已读入起始 '{' 的对象的字段流，prefix 是该对象
298	// 的位置前缀（根对象为空，其余层次以 "." 结尾，如 "requests[1]."）。每个键
299	// 按所在层次的 schema 分派：已识别数值字段检查是否写成 null，已识别数组字段
300	// 递归扫描元素，其余键的值整体跳过。返回第一个数值 null 的完整位置。
301	func scanObjectFields(dec *json.Decoder, schema *objectSchema, prefix string) string {
302		for dec.More() {
303			key, ok := decodeKey(dec)
304			if !ok {
305				return ""
306			}
307			if name, ok := schema.numericName(key); ok {
308				if nullScalarPath(dec) {
309					return prefix + name
310				}
311				continue
312			}
313			if field, ok := schema.arrayField(key); ok {
314				if path := scanObjectArray(dec, field.elem, prefix+field.name); path != "" {
315					return path
316				}
317				continue
318			}
319			skipValue(dec)
320		}
321		return ""
322	}
323	
324	// scanObjectArray 扫描一个对象数组字段的完整 token 流（数组字段重复出现时由
325	// 调用方对每一份数组分别调用），arrayPath 是数组自身的位置（如 "log" 或
326	// "requests[r].entries"），返回第一个数值 null 的完整位置。
327	func scanObjectArray(dec *json.Decoder, elem *objectSchema, arrayPath string) string {
328		tok, err := dec.Token()
329		if err != nil {
330			return ""
331		}
332		if tok != json.Delim('[') {
333			// 数组字段本身为 null 或其他类型（如被写成对象）：沿用既有处理，
334			// 类型错误由随后的类型化解码按既有格式报告。这里必须把整个值消费
335			// 完——起始分隔符已经读出，若就此返回，调用方的循环会落到对象内部，
336			// 把其中的 term/index 等字段当成外层已识别字段，其后的真实数值
337			// null 也会被漏检。
338			if d, ok := tok.(json.Delim); ok {
339				skipRest(dec, d)
340			}
341			return ""
342		}
343		for i := 0; dec.More(); i++ {
344			tok, err := dec.Token()
345			if err != nil {
346				return ""
347			}
348			if tok != json.Delim('{') {
349				// 非对象元素不可能含已识别字段；若它本身是容器仍要消费完整。
350				if d, ok := tok.(json.Delim); ok {
351					skipRest(dec, d)
352				}
353				continue
354			}
355			prefix := fmt.Sprintf("%s[%d].", arrayPath, i)
356			if path := scanObjectFields(dec, elem, prefix); path != "" {
357				return path
358			}
359			if _, err := dec.Token(); err != nil { // 元素对象的 '}'
360				return ""
361			}
362		}
363		if _, err := dec.Token(); err != nil { // 数组的 ']'
364			return ""
365		}
366		return ""
367	}
368	
369	// decodeKey 读取并断言下一个 token 是对象键。
370	func decodeKey(dec *json.Decoder) (string, bool) {
371		tok, err := dec.Token()
372		if err != nil {
373			return "", false
374		}
375		key, ok := tok.(string)
376		return key, ok
377	}
378	
379	// nullScalarPath 消费一个已识别数值字段的值 token 流，报告该次出现是否被
380	// 显式写成 null。值为对象或数组时整体跳过（结构异常的输入留给类型化解码
381	// 报告既有错误）。
382	func nullScalarPath(dec *json.Decoder) bool {
383		tok, err := dec.Token()
384		if err != nil {
385			return false
386		}
387		if tok == nil {
388			return true
389		}
390		if d, ok := tok.(json.Delim); ok {
391			skipRest(dec, d)
392		}
393		return false
394	}
395	
396	// skipValue 读取并消费一个完整的 JSON 值（标量或容器）。
397	func skipValue(dec *json.Decoder) {
398		tok, err := dec.Token()
399		if err != nil {
400			return
401		}
402		if d, ok := tok.(json.Delim); ok {
403			skipRest(dec, d)
404		}
405	}
406	
407	// skipRest 消费一个容器剩余的 token 流，open 是已经读出的起始分隔符；
408	// 起始分隔符不是 '{' / '[' 时无需消费，直接返回。
409	func skipRest(dec *json.Decoder, open json.Delim) {
410		if open != '{' && open != '[' {
411			return
412		}
413		depth := 1
414		for depth > 0 {
415			tok, err := dec.Token()
416			if err != nil {
417				return
418			}
419			if d, ok := tok.(json.Delim); ok {
420				switch d {
421				case '{', '[':
422					depth++
423				case '}', ']':
424					depth--
425				}
426			}
427		}
428	}
